  const packageTable=`<div class="sponsor-table-wrap"><table class="sponsor-package-table"><thead><tr><th>${isTh?'สิ่งที่ได้รับ':'What is included'}</th><th>Basic <span>${isTh?'ฟรี':'Free'}</span></th><th>Featured <span>${isTh?'แพ็กเกจชำระเงิน':'Paid package'}</span></th></tr></thead><tbody>${packageRows.map(r=>`<tr><th>${r[0]}</th><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div>`;
  const providerBody=`<div class="eyebrow">/ ${isTh?'สำหรับผู้ให้บริการ':'FOR MARTECH PROVIDERS'}</div><h1>${isTh?'เลือกการมองเห็นที่เหมาะกับคุณ':'Choose the visibility that fits your goals.'}</h1><p class="route-intro">${isTh?'ลงข้อมูลพื้นฐานได้ฟรี หรือเลือก Featured เพื่อแสดงรายละเอียดผลิตภัณฑ์ได้มากขึ้น พร้อมเครื่องมือเพิ่มการมองเห็นและติดตามผล':'List your basic product information for free, or choose Featured for richer content, more visibility options, and performance insights.'}</p><div class="sponsor-tier-cards"><article class="sponsor-tier-card"><span class="eyebrow">BASIC</span><h2>${isTh?'เริ่มต้นฟรี':'Start for free'}</h2><p>${isTh?'ให้ผู้ซื้อค้นพบและรู้จักข้อมูลผลิตภัณฑ์พื้นฐาน':'Help buyers discover your product with a standard profile.'}</p><ul data-package-benefits="basic"><li>${isTh?'ข้อมูลบริษัทและผลิตภัณฑ์พื้นฐาน':'Basic company and product details'}</li><li>${isTh?'แสดงในผลค้นหาแบบ Organic':'Organic search and category listing'}</li><li>${isTh?'ลิงก์ไปเว็บไซต์บริษัท':'Link to your website'}</li></ul><span class="sponsor-plan-price" data-package-value="basic.price">${isTh?'ฟรี':'Free'}</span><div class="sponsor-meta"><span>${isTh?'ระยะเวลา':'Duration'}: <b data-package-value="basic.duration">${isTh?'ต่อเนื่อง; ทบทวนข้อมูลเป็นระยะ':'Ongoing; review periodically'}</b></span><span data-package-value="basic.slots">${isTh?'แสดงผล Organic ไม่มีตำแหน่งชำระเงิน':'Organic listing; no paid placement'}</span></div></article><article class="sponsor-tier-card featured-tier"><span class="badge">FEATURED · PAID</span><h2>${isTh?'เพิ่มข้อมูล เพิ่มโอกาส':'Showcase more. Reach further.'}</h2><p>${isTh?'โปรไฟล์แบบ Rich Content พร้อม CTA, Analytics และสิทธิ์เข้าพื้นที่ Sponsored':'A richer profile with stronger conversion tools, analytics, and sponsored visibility eligibility.'}</p><ul data-package-benefits="featured"><li>${isTh?'ข้อมูลรายละเอียด ภาพ วิดีโอ และ Case study มากขึ้น':'More product details, images, videos, and case studies'}</li><li>${isTh?'CTA สำหรับเว็บไซต์, Demo หรือ Free Trial':'CTAs for website, demo, or free trial'}</li><li>${isTh?'ข้อมูล SEO/AEO/GEO และรายงานรายเดือน':'SEO/AEO/GEO content and monthly performance report'}</li></ul><span class="sponsor-plan-price" data-package-value="featured.price">${isTh?'สอบถามราคา':'Contact for pricing'}</span><div class="sponsor-meta"><span>${isTh?'ระยะเวลา':'Duration'}: <b data-package-value="featured.duration">${isTh?'ยืนยันในข้อเสนอหรือสัญญา':'Confirm in package agreement'}</b></span><span data-package-value="featured.slots">${isTh?'ตำแหน่งขึ้นกับพื้นที่และการจัดสรร ไม่รับประกัน':'Placement subject to inventory; not guaranteed'}</span></div></article></div><section class="sponsor-packages" id="sponsor-packages"><div class="eyebrow">/ ${isTh?'เปรียบเทียบแพ็กเกจ':'PACKAGE COMPARISON'}</div><h2>${isTh?'รายละเอียดสิทธิประโยชน์':'What each package includes'}</h2>${packageTable}</section><section class="sponsor-conditions"><div class="eyebrow">/ ${isTh?'เงื่อนไขการแสดงผล':'PLACEMENT & CONTENT CONDITIONS'}</div><div class="sponsor-condition-grid"><article><h3>${isTh?'ตำแหน่ง Sponsored':'Sponsored positions'}</h3><p>${isTh?'แพ็กเกจ Featured มีสิทธิ์เข้าพื้นที่ Sponsored และได้รับ Featured badge ตำแหน่งแสดงผลขึ้นกับพื้นที่และการจัดสรรของแพลตฟอร์ม':'Featured includes a Featured badge and eligibility for sponsored placements. Placement depends on available inventory and platform allocation.'}</p></article><article><h3>${isTh?'ตรวจสอบข้อมูลก่อนเผยแพร่':'Review before publishing'}</h3><p>${isTh?'ข้อมูลบริษัทและผลิตภัณฑ์ต้องผ่านการตรวจสอบความครบถ้วนและข้อเท็จจริงก่อนเผยแพร่':'Company and product information is reviewed for completeness and factual accuracy before publishing.'}</p></article><article><h3>${isTh?'แก้ไขได้ตามแพ็กเกจ':'Updates follow package limits'}</h3><p>${isTh?'Basic แก้ไขพื้นฐานได้ 1 ครั้งตอนส่งข้อมูลครั้งแรก ส่วน Featured ขอแก้ไขระหว่างปีได้สูงสุด 2 ครั้ง ภายใต้การตรวจสอบ':'Basic includes one initial basic edit. Featured includes up to two update requests during the year, subject to review.'}</p></article><article><h3>${isTh?'แยกโฆษณาจากอันดับธรรมชาติ':'Clear sponsor disclosure'}</h3><p>${isTh?'ทุกตำแหน่งที่ได้รับการสนับสนุนจะติดป้ายชัดเจน การชำระเงินไม่เปลี่ยนเกณฑ์บรรณาธิการหรืออันดับ Organic':'Sponsored placements are clearly labelled. Payment does not change editorial criteria or organic rankings.'}</p></article></div><p class="sponsor-note">* ${isTh?'ไฟล์แพ็กเกจไม่ได้ระบุราคาและจำนวนตำแหน่งที่รับประกัน จึงแสดงราคาเป็น “สอบถามทีมงาน” และไม่รับประกันการได้ตำแหน่ง Sponsor เฉพาะจุด':'The package sheet does not specify a price or guaranteed slot count. Pricing is shown as “contact the team,” and specific placements are not guaranteed.'}</p></section><p class="disclosure">${isTh?'หน้านี้เป็น mockup ตัวอย่าง Sponsor และรายงาน Analytics ยังไม่เชื่อมระบบจริง การแสดง Featured ไม่ได้ยืนยันสถานะการซื้อแพ็กเกจของบริษัทใด':'This page is a prototype. Sponsor placements and analytics reports are not connected to live systems, and a Featured preview does not confirm a company purchase.'}</p>`;
